package com.bank.settlement;

import java.math.BigDecimal;
import java.util.logging.*;

public class SettlementDemo {
    private static final Logger log = Logger.getLogger(SettlementDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rajesh's sorted debit feed (SAV2001): 1,000 then 5,000 then 9,000
        SettlementNode rajesh = build(
            new String[]{"SAV2001-D1", "SAV2001-D2", "SAV2001-D3"},
            new String[]{"1000", "5000", "9000"});

        // Priya's sorted debit feed (CUR3001): 2,000 then 5,000 then 12,000
        SettlementNode priya = build(
            new String[]{"CUR3001-D1", "CUR3001-D2", "CUR3001-D3"},
            new String[]{"2000", "5000", "12000"});

        log.info("Merging two sorted settlement feeds into one ascending stream");
        SettlementMerger merger = new SettlementMerger();
        SettlementNode merged = merger.merge(rajesh, priya);

        int position = 1;
        for (SettlementNode n = merged; n != null; n = n.next) {
            final int p = position++;
            final SettlementNode cur = n;
            log.info(() -> "Position " + p + " -> " + cur.txnId + " amount Rs." + cur.amount);
        }
        log.info("Single sorted settlement stream produced successfully");
    }

    // Helper to build a sorted linked list from parallel arrays
    private static SettlementNode build(String[] ids, String[] amounts) {
        SettlementNode dummy = new SettlementNode(null, BigDecimal.ZERO);
        SettlementNode tail = dummy;
        for (int i = 0; i < ids.length; i++) {
            tail.next = new SettlementNode(ids[i], new BigDecimal(amounts[i]));
            tail = tail.next;
        }
        return dummy.next;
    }
}

// ─── Would be in model/SettlementNode.java in a real project ───
class SettlementNode {
    String txnId;
    BigDecimal amount;
    SettlementNode next;

    SettlementNode(String txnId, BigDecimal amount) {
        this.txnId = txnId;
        this.amount = amount;
    }
}

// ─── Would be in service/SettlementMerger.java in a real project ───
class SettlementMerger {
    // Merge two sorted node chains into one sorted chain. O(n+m) time, O(1) space.
    SettlementNode merge(SettlementNode a, SettlementNode b) {
        SettlementNode dummy = new SettlementNode(null, BigDecimal.ZERO);
        SettlementNode tail = dummy;

        while (a != null && b != null) {
            // compareTo <= 0 means a.amount is smaller or equal -> take a first (stable)
            if (a.amount.compareTo(b.amount) <= 0) {
                tail.next = a;
                a = a.next;
            } else {
                tail.next = b;
                b = b.next;
            }
            tail = tail.next;
        }
        // Attach the remainder in one move; it is already sorted
        tail.next = (a != null) ? a : b;
        return dummy.next;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
